// Lead r6 (2026-11-17): ONE moving-gameplay audit method for every playable screen 04–08 (read-only).
// From the screen's approved-view checkpoint it rides the real game simulation forward / steers and screenshots what
// the live camera sees, so every screen is judged with the same shots. Generalises tools/match08/motion08.mjs.
// Run from the checkout to test (vite serves the current directory):
//   node <path>/motion_audit.mjs <screen 04..08> <outDir> [query]
import { mkdirSync, writeFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [SCREEN, OUT, Q = ''] = process.argv.slice(2);
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5270 + Number(SCREEN));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
const log = [];
// [name, forward distance in world units from the checkpoint (or 'tN' = fraction N of the rest of the stage), steer]
const SHOTS = [
  ['a00_approved_view', 0, null],
  ['f03_forward3u', 3, null], ['f06_forward6u', 6, null], ['f10_forward10u', 10, null], ['f20_forward20u', 20, null],
  ['s_left_steer', 6, -1], ['s_right_steer', 6, 1], ['s_left_hard', 12, -1], ['s_right_hard', 12, 1],
  ['t33_through_screen', 't0.33', null], ['t66_through_screen', 't0.66', null], ['t95_through_screen', 't0.95', null],
];
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  for (const [name, dist, steer] of SHOTS) {
    const st = await page.evaluate(async ([id, dist, steer]) => {
      const r = window.__rainbow; r.goto(id);
      const s0 = r.state().s;
      const stg = r.course.stage(id);
      const s1 = stg.s1 ?? (stg.s0 + (stg.length ?? 0));
      const target = typeof dist === 'string' ? s0 + Number(dist.slice(1)) * Math.max(0, s1 - s0) : s0 + dist;
      r.setSteer(steer);
      let n = 0; while (r.state().s < target - 1e-3 && n < 4000) { r.step(1); n++; }
      r.setSteer(null);
      r.run(true); await new Promise((res) => requestAnimationFrame(() => requestAnimationFrame(res))); r.run(false);
      return { ...r.state(), frames: n, s0, s1, target };
    }, [SCREEN, dist, steer]);
    await page.waitForTimeout(150);
    await page.screenshot({ path: `${OUT}/${name}.png` });
    log.push({ name, dist, steer, ...st });
    console.log(SCREEN, name, 's', st.s, 'lat', st.lat, 'stage', st.stage, 'frames', st.frames);
  }
} finally {
  writeFileSync(`${OUT}/motion.json`, JSON.stringify({ screen: SCREEN, query: Q, shots: log }, null, 1));
  await browser.close(); await vite.close?.();
}
#!/usr/bin/env node
// Lead r13 (2026-11-18): a short REAL-GAMEPLAY swimming clip for any playable screen 04–08 (read-only).
// Starts at the screen's checkpoint and rides the real game simulation (Benny, camera rig, course, coins unchanged) with
// the shader clock running: straight, then left, then right, then straight — one frame per 1/fps s → OUT/0000.png …
// Generalises scripts/proj05-move.mjs --zigzag. Encode: ffmpeg -framerate 24 -i OUT/%04d.png -pix_fmt yuv420p clip.mp4
//   node tools/lead_r13/swim_clip.mjs <screen 04..08> <outDir> <seconds> [query]
import { mkdirSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
const { loadPlaywright, CHROMIUM_ARGS, startVite } = await import(pathToFileURL(`${process.cwd()}/scripts/lib/pw.mjs`).href);
const [SCREEN, OUT, SECS = '6', Q = ''] = process.argv.slice(2);
const fps = 24;
mkdirSync(OUT, { recursive: true });
const { chromium } = loadPlaywright();
const vite = await startVite(5280 + Number(SCREEN));
const browser = await chromium.launch({ args: CHROMIUM_ARGS });
try {
  const page = await browser.newPage({ viewport: { width: 864, height: 1536 }, deviceScaleFactor: 1 });
  page.on('pageerror', (e) => console.error('pageerror', e.message));
  await page.goto(`${vite.url}/?qa=1&dpr=1${Q ? '&' + Q : ''}`);
  await page.waitForFunction(() => window.__rainbow?.ready === true || window.__error, null, { timeout: 300000 });
  await page.evaluate((id) => window.__rainbow.goto(id), SCREEN);
  const n = Math.round(Number(SECS) * fps);
  for (let i = 0; i < n; i++) {
    const ph = i / n;                                   // straight 0–0.3, left 0.3–0.55, right 0.55–0.8, straight
    const dir = ph < 0.3 ? null : ph < 0.55 ? -1 : ph < 0.8 ? 1 : null;
    await page.evaluate(([t, dt, dir]) => { const R = window.__rainbow; R.setSteer(dir); R.freezeAt(t); R.step(Math.round(dt * 60), 1 / 60); R.freezeAt(t + dt); R.step(1, 1e-4); }, [12 + i / fps, 1 / fps, dir]);
    await page.evaluate(() => window.__rainbow.drawList());
    await page.screenshot({ path: `${OUT}/${String(i).padStart(4, '0')}.png` });
  }
  console.log('frames', n);
} finally {
  await browser.close();
  await vite.close();
}

1	/**
2	 * `?match06=1` — Screen 06 approved-picture test (2026-11-17, qa/match/06/NOTES.md), the Screen 08 method.
3	 * REAL 3D proxy geometry of "Crest the Rinse Arch", built around the game's own 06 river (which under the switch follows
4	 * the painted river: course.ts + assets/textures/match06/path06.json) and seen from the locked approved-view camera
5	 * (tools/match06/fit_river06.py → cam06_locked.json; layout tools/match06/make_tiles06.py → proj06.json):
6	 *   * the perforated tunnel = a tube of radius R around the river (centre hA above the water) from behind the camera
7	 *     into 07, continued straight along the river's heading so the painted far rings stay concentric
8	 *   * the river floor = the water surface: the game river's width + 1 u of foam bank each side (<= Lfloor)
9	 *   * a dark end cap far down the tunnel
10	 * Every surface is textured by camera projection of the user's ORIGINAL approved pixels (HUD, title, Benny and coins
11	 * provisionally filled locally: plate06_hybrid.png) from the locked camera, so the locked view shows the approved scenery
12	 * and a moving camera sees it on geometry (parallax). Surfaces the picture never showed (or showed edge-on / far smaller)
13	 * get RING-STRUCTURED tiles unwrapped from the artwork in the surface's own coordinates (tube: wall angle x s, the
14	 * painted gold rings + slotted metal; floor: lateral x s, the painted water) — stretch x magnification guard + projector
15	 * depth test. The shader undoes the game's post chain (PROJ05_INVERSE) and takes no fog.
16	 * Without the switch nothing in this file runs and the game is unchanged.
17	 */
18	import * as THREE from 'three';
19	import { mergeGeometries } from 'three/examples/jsm/utils/BufferGeometryUtils.js';
20	import { PROJ05_INVERSE } from '../vfx/waterRibbon';
21	import type { Course } from './course';
22	
23	interface Layout06 {
24	  camera: { matrixWorld: number[]; fov: number; size: [number, number]; pos: number[] };
25	  R: number;
26	  hA: number;
27	  ext: number;
28	  s0: number;
29	  s1: number;
30	  Lfloor: number;
31	  tiles: {
32	    tube: { wallAngle: [number, number]; period: number; anglePeriod: number };
33	    floor: { lateralPeriod: number; period: number };
34	    floor2?: { lateralPeriod: number; period: number };
35	    r6?: { Wc: number; Wb: number; hb: number; river: { period: number }; foamPeriod: number };
36	  };
37	}
38	
39	export interface Match06 {
40	  group: THREE.Group;
41	  bakeDepth(renderer: THREE.WebGLRenderer): void;
42	  sync(renderer: THREE.WebGLRenderer, w: number, h: number): void;
43	  /** r7 `&m06bub=1`: 0 at the approved viewpoint .. 1 once the camera has left it (the painting only covers that view) */
44	  away(cam: THREE.Vector3): number;
45	  /** r7 `&m06foam=1`: show the 3D foam clouds once the camera has left the approved view (a = away()) */
46	  setAway(a: number): void;
47	}
48	
49	const VERT = /* glsl */ `
50	uniform mat4 uProjVP;
51	attribute vec2 aTile;
52	attribute vec2 aLS;
53	varying vec4 vProj;
54	varying vec3 vW;
55	varying vec3 vN;
56	varying vec2 vTile;
57	varying vec2 vLS;
58	void main() {
59	  vec4 wp = modelMatrix * vec4(position, 1.0);
60	  vProj = uProjVP * wp;
61	  vW = wp.xyz;
62	  vTile = aTile;
63	  vLS = aLS;
64	  vN = normalize(mat3(modelMatrix) * normal);
65	  gl_Position = projectionMatrix * viewMatrix * wp;
66	}`;
67	
68	const FRAG = /* glsl */ `
69	uniform sampler2D uPlate;
70	uniform sampler2D uDepth;
71	uniform float uUseDepth;
72	uniform vec2 uNearFar;
73	uniform sampler2D uTile;
74	uniform vec3 uProjPos;
75	uniform vec4 uPjPost;
76	uniform vec2 uPjRes;
77	uniform vec3 uDbg;
78	uniform sampler2D uMask;
79	uniform float uFloor;
80	uniform float uUseMask;
81	// r6 (qa/match/06/NOTES.md): uGeo = narrow fitted river (lateral |l| <= Wc water, Wc..Wb foam bank); uR6 = river material
82	// built from the approved painted water, world-anchored and flowing downstream (uR6p = Wc, Wb, river period, foam period)
83	uniform float uGeo;
84	uniform float uR6;
85	uniform vec4 uR6p;
86	uniform float uTime;
87	uniform sampler2D uRiver;
88	uniform sampler2D uFoam;
89	// r7 m06ring: modeled gold rings (uRing = 1) around the straight tunnel axis (origin, direction, right, up)
90	uniform float uRing;
91	uniform vec3 uAxO;
92	uniform vec3 uAxD;
93	uniform vec3 uAxR;
94	uniform vec3 uAxU;
95	uniform float uRingH;
96	uniform float uBendAng; // r11 m06bend: ring bulb angle per vertex (vTile.x) instead of around the straight axis
97	uniform float uPanel;
98	varying vec4 vProj;
99	varying vec3 vW;
100	varying vec3 vN;
101	varying vec2 vTile;
102	varying vec2 vLS;
103	${PROJ05_INVERSE}
104	float linZ(float d) { float n = uNearFar.x, f = uNearFar.y; float z = d * 2.0 - 1.0; return 2.0 * n * f / (f + n - z * (f - n)); }
105	void main() {
106	  // ring-structured tile in the surface's own coordinates (mirrored repeat: no seams)
107	  vec3 pc = texture2D(uTile, vTile).rgb;
108	  vec3 nn = normalize(vN);
109	  float al = abs(vLS.x);
110	  if (uR6 > 0.5 && uFloor > 0.5) {
111	    float sF = vLS.y - uTime * 1.2;
112	    float ax = clamp(vLS.x / (2.0 * uR6p.x) + 0.5, 0.0, 1.0);
113	    vec3 r1 = texture2D(uRiver, vec2(ax, sF / uR6p.z)).rgb;
114	    vec3 r2 = texture2D(uRiver, vec2(ax, sF / (uR6p.z * 1.37) + 0.43)).rgb;
115	    float bw = 0.5 + 0.5 * sin(vLS.y * 0.37 + vLS.x * 0.6) * sin(vLS.y * 0.13 + 1.7);
116	    vec3 riv = mix(r1, r2, smoothstep(0.25, 0.75, bw));
117	    float fr = pow(1.0 - abs(dot(nn, normalize(cameraPosition - vW))), 4.0);
118	    riv += fr * 0.22 * vec3(0.9, 0.85, 1.0);
119	    vec3 fo = texture2D(uFoam, vec2((al - uR6p.x) / (uR6p.y - uR6p.x), vLS.y / uR6p.w)).rgb;
120	    pc = mix(riv, fo, smoothstep(uR6p.x - 0.3, uR6p.x + 0.15, al));
121	  }
122	  if (uRing > 0.5) {
123	    // polished gold band: reflects the warm glow down the tunnel and the purple walls; a row of warm bulbs in the groove
124	    vec3 V = normalize(cameraPosition - vW);
125	    vec3 n2 = dot(nn, V) < 0.0 ? -nn : nn;
126	    vec3 Rf = reflect(-V, n2);
127	    float fw = dot(Rf, uAxD);
128	    vec3 env = mix(vec3(0.46, 0.20, 0.55), vec3(1.0, 0.80, 0.50), smoothstep(-0.35, 0.9, fw));
129	    env = mix(env, vec3(1.0, 0.96, 0.86), pow(max(fw, 0.0), 10.0));
130	    float fres = pow(1.0 - max(dot(n2, V), 0.0), 3.0);
131	    vec3 g = vec3(1.0, 0.60, 0.20) * (0.24 + 0.95 * env) + fres * vec3(1.0, 0.82, 0.55) * 0.45;
132	    g += vec3(1.0, 0.9, 0.7) * 0.5 * pow(max(dot(Rf, normalize(uAxD + uAxU * 0.35)), 0.0), 40.0);
133	    // r7b: the painted bands' bright yellow-white lines on the lips and band edges
134	    float lipL = smoothstep(0.07, 0.0, abs(abs(vLS.x) - 0.22)) + smoothstep(0.09, 0.0, abs(abs(vLS.x) - (uRingH - 0.12)));
135	    g = mix(g, vec3(1.0, 0.90, 0.60), clamp(lipL, 0.0, 1.0) * 0.55);
136	    vec3 q = vW - uAxO;
137	    float ang = uBendAng > 0.5 ? vTile.x : atan(dot(q, uAxU), dot(q, uAxR));
138	    // r7b: fewer, bigger warm bulbs with a soft halo (the painted rings' amber light dots)
139	    float cell = fract(ang / 6.2831853 * 56.0) - 0.5;
140	    float bd = length(vec2(cell * 2.6, vLS.x / 0.16));
141	    g += vec3(1.0, 0.62, 0.28) * 0.35 * smoothstep(0.3, 0.0, abs(vLS.x)) + vec3(1.0, 0.7, 0.35) * 0.5 * smoothstep(1.1, 0.0, bd);
142	    pc = mix(g, vec3(1.0, 0.96, 0.84), smoothstep(0.5, 0.15, bd));
143	  }
144	  if (uPanel > 0.5 && uFloor < 0.5 && uRing < 0.5) {
145	    // r7b m06ring: crisp perforated lilac washer metal between the rings (the painted panels: rows of short dark rounded
146	    // slots running around the tunnel, pink-white sheen toward the glow), instead of the magnified blurry far-ring crop
147	    vec3 q = vW - uAxO;
148	    float al = dot(q, uAxD);
149	    vec3 qr = q - uAxD * al;
150	    float arc = atan(dot(qr, uAxU), dot(qr, uAxR)) * length(qr);
151	    vec3 V = normalize(cameraPosition - vW);
152	    vec3 n2 = dot(nn, V) < 0.0 ? -nn : nn;
153	    float fw = dot(reflect(-V, n2), uAxD);
154	    // colours measured from the approved picture's walls (display values): shadow / median / lit magenta-purple,
155	    // lilac-blue toward the glow, near-black magenta slots (3-8 % of the wall)
156	    float lit = smoothstep(-0.7, 0.8, fw);
157	    vec3 base = mix(vec3(0.42, 0.19, 0.50), vec3(0.67, 0.34, 0.74), lit);
158	    base = mix(base, vec3(0.56, 0.38, 0.88), 0.45 * smoothstep(0.2, 0.95, fw));
159	    base += vec3(0.9, 0.6, 0.95) * 0.16 * pow(max(fw, 0.0), 8.0);
160	    float row = floor(al / 0.55);
161	    vec2 p = vec2((fract(arc / 0.62 + 0.5 * mod(row, 2.0)) - 0.5) * 0.62, (fract(al / 0.55) - 0.5) * 0.55);
162	    float d = length(max(abs(p) - vec2(0.13, 0.03), 0.0)) - 0.03;
163	    float aa = max(fwidth(d), 1e-4);
164	    float slot = (1.0 - smoothstep(-aa, aa, d)) * (1.0 - smoothstep(20.0, 60.0, distance(cameraPosition, vW)));
165	    float lip = (1.0 - smoothstep(-aa, aa, abs(d - 0.03) - 0.012)) * step(0.0, -p.y);
166	    vec3 pan = mix(base, vec3(0.24, 0.02, 0.22), slot) + vec3(0.85, 0.55, 0.95) * 0.18 * lip * (1.0 - slot);
167	    pc = mix(pc, pan, 0.85);
168	  }
169	  vec3 t = pc;
170	  float cp = abs(dot(nn, normalize(uProjPos - vW))), cc = abs(dot(nn, normalize(cameraPosition - vW)));
171	  // stretch + magnification guard: the projection is used where the current view sees the surface no more face-on and
172	  // no more magnified than the approved view did (incidence-cosine ratio x distance ratio = 1 in the approved view)
173	  float mag = (cc / max(cp, 1e-3)) * (distance(uProjPos, vW) / max(distance(cameraPosition, vW), 1e-3));
174	  // r6 m06flow: on the river the flowing painted-water material takes over sooner from the stretched projection
175	  float keep = uR6 > 0.5 && uFloor > 0.5 ? 1.0 - smoothstep(1.4, 3.0, mag) : 1.0 - smoothstep(2.5, 6.0, mag);
176	  if (vProj.w > 0.0) {
177	    vec3 ndc = vProj.xyz / vProj.w;
178	    vec2 uv = ndc.xy * 0.5 + 0.5;
179	    if (uv.x >= 0.0 && uv.x <= 1.0 && uv.y >= 0.0 && uv.y <= 1.0) {
180	      float vis = 1.0;
181	      if (uUseDepth > 0.5) {
182	        float zs = linZ(texture2D(uDepth, uv).r), zf = linZ(ndc.z * 0.5 + 0.5);
183	        vis = 1.0 - smoothstep(0.015 * zs, 0.04 * zs + 0.05, zf - zs);
184	      }
185	      float w = vis * keep;
186	      // r3 masks (tools/match06/make_masks06.py): where the river floor carries painted pixels that are not water (G: the
187	      // tunnel wall seen through the crest loop / beside the river) or Benny's blurry provisional fill (R), the floor
188	      // shows the painted-water tile as soon as the camera leaves the approved view (the approved view is unchanged)
189	      if (uFloor > 0.5 && uUseMask > 0.5) {
190	        vec4 mk = texture2D(uMask, uv);
191	        float away = smoothstep(0.2, 1.2, distance(cameraPosition, uProjPos));
192	        float inWater = uGeo > 0.5 ? 1.0 - smoothstep(uR6p.x - 0.2, uR6p.x + 0.1, al) : 1.0;
193	        w *= 1.0 - max(mk.r, mk.g) * away * inWater;
194	      }
195	      // r6 m06geo: painted WATER that lands on the tunnel wall (the crest-top water / far stream beside the narrow river)
196	      // shows the ring-structured wall tile once the camera leaves the approved view (the real river geometry carries
197	      // the water there)
198	      if (uFloor < 0.5 && uGeo > 0.5 && uUseMask > 0.5) {
199	        float awayT = smoothstep(0.2, 1.2, distance(cameraPosition, uProjPos));
200	        w *= 1.0 - (1.0 - texture2D(uMask, uv).g) * awayT;
201	      }
202	      // m06ring: the modeled rings show the approved pixels only AT the approved view, their own 3D gold once away
203	      if (uRing > 0.5) w *= 1.0 - smoothstep(0.2, 1.2, distance(cameraPosition, uProjPos));
204	      t = mix(pc, texture2D(uPlate, uv).rgb, w);
205	    }
206	  }
207	  gl_FragColor = vec4(pjInverse(t), 1.0);
208	  if (uDbg.x + uDbg.y + uDbg.z > 0.0) gl_FragColor.rgb = mix(gl_FragColor.rgb, uDbg, 0.45);
209	}`;
210	
211	const tex = (f: string) => new URL(`../../assets/textures/match06/${f}`, import.meta.url).href;
212	
213	export async function buildMatch06(course: Course): Promise<Match06> {
214	  const L: Layout06 = await fetch(tex('proj06.json')).then((r) => r.json());
215	  const loader = new THREE.TextureLoader();
216	  const plate = await loader.loadAsync(tex('plate06_hybrid.png'));
217	  plate.colorSpace = THREE.NoColorSpace; // raw display values: the shader inverts the post chain itself
218	  plate.minFilter = THREE.LinearMipmapLinearFilter;
219	  plate.anisotropy = 8;
220	
221	  // the projector = the locked game camera the picture was matched to (far enough for the deep painted tunnel)
222	  const [W, H] = L.camera.size;
223	  const proj = new THREE.PerspectiveCamera(L.camera.fov, W / H, 0.3, L.ext + 160);
224	  proj.matrixWorld.fromArray(L.camera.matrixWorld);
225	  proj.matrixWorld.decompose(proj.position, proj.quaternion, proj.scale);
226	  proj.matrixWorldInverse.copy(proj.matrixWorld).invert();
227	  proj.updateProjectionMatrix();
228	  const projVP = new THREE.Matrix4().multiplyMatrices(proj.projectionMatrix, proj.matrixWorldInverse);
229	
230	  const depthRT = new THREE.WebGLRenderTarget(1024, Math.round((1024 * H) / W), { depthBuffer: true });
231	  depthRT.depthTexture = new THREE.DepthTexture(depthRT.width, depthRT.height, THREE.UnsignedIntType);
232	  const shared = {
233	    uPlate: { value: plate },
234	    uDepth: { value: depthRT.depthTexture as THREE.Texture },
235	    uUseDepth: { value: 0 },
236	    uNearFar: { value: new THREE.Vector2(proj.near, proj.far) },
237	    uProjVP: { value: projVP },
238	    uPjPost: { value: new THREE.Vector4(0.86, 1.36, 1.15, 0.18) },
239	    uPjRes: { value: new THREE.Vector2(W, H) },
240	    uProjPos: { value: proj.position.clone() },
241	    uTime: { value: 0 },
242	  };
243	  const loadTile = async (name: string) => {
244	    const t = await loader.loadAsync(tex(`tile_${name}.png`));
245	    t.colorSpace = THREE.NoColorSpace; t.wrapS = t.wrapT = THREE.MirroredRepeatWrapping; t.anisotropy = 8;
246	    t.minFilter = THREE.LinearMipmapLinearFilter; return t;
247	  };
248	  // r3 (2026-11-17, qa/match/06/NOTES.md): masks + rectified repeating floor tile; `&m06v=2` = the round-2 result
249	  const v2 = typeof location !== 'undefined' && new URLSearchParams(location.search).get('m06v') === '2';
250	  const TF2 = !v2 ? L.tiles.floor2 : undefined;
251	  const [tTube, tFloor] = await Promise.all([loadTile('tube'), loadTile(TF2 ? 'floor2' : 'floor')]);
252	  if (TF2) tFloor.wrapT = THREE.RepeatWrapping; // seamless along the river (mirrored only across it)
253	  // r6 switches (each its own factor): `&m06geo=1` narrow river + foam banks + tunnel walls down to the banks;
254	  // `&m06flow=1` river / foam material from the approved painted water, flowing (needs m06geo)
255	  const qs = typeof location !== 'undefined' ? new URLSearchParams(location.search) : null;
256	  const R6 = !v2 ? L.tiles.r6 : undefined;
257	  const GEO = !!R6 && qs?.get('m06geo') === '1';
258	  const FLOW = GEO && qs?.get('m06flow') === '1';
259	  const mask = v2 ? null : await loader.loadAsync(tex('mask06.png'));
260	  if (mask) { mask.colorSpace = THREE.NoColorSpace; mask.generateMipmaps = false; mask.minFilter = THREE.LinearFilter; }
261	  let tRiver: THREE.Texture | null = null, tFoam: THREE.Texture | null = null;
262	  if (FLOW) {
263	    [tRiver, tFoam] = await Promise.all([loader.loadAsync(tex('tile_river6.png')), loader.loadAsync(tex('tile_foam6.png'))]);
